func:
// แยกข้อความตามชนิด: status (รายวินาที) -> ช่อง 1, event (เหตุการณ์) -> ช่อง 2
const p = msg.payload;
if (typeof p !== 'object' || !p.type) {
    node.warn('ได้ข้อความที่ไม่ใช่ JSON ของโปรเจกต์: ' + JSON.stringify(p));
    return null;
}
node.status({fill: 'green', shape: 'dot', text: p.type + ' ' + (p.time || '')});
if (p.type === 'status') return [msg, null];
if (p.type === 'event') return [null, msg];
return null;

// 4a. แปลง JSON เป็น InfluxDB Line Protocol แล้วยิง HTTP เข้า /api/v2/write
// status -> measurement golf_status (ทุกวินาที), event -> golf_event
const p = msg.payload;
const tag = v => String(v).replace(/[ ,=]/g, '\\$&');
const str = v => '"' + String(v).replace(/\\/g, '\\\\').replace(/"/g, '\\"') + '"';
const c = p.colors || {};
const colorFields = `white=${c.White || 0}i,neon=${c.Neon || 0}i,pink=${c.Pink || 0}i`;

let line;
if (p.type === 'status') {
    line = `golf_status,device=${tag(p.device)} golf_count=${p.golf_count}i,` +
           `reject_count=${p.reject_count}i,${colorFields},fps=${Number(p.fps) || 0},` +
           `frames=${p.frames || 0}i ${p.ts}`;
} else {
    line = `golf_event,device=${tag(p.device)},kind=${tag(p.kind)} golf_count=${p.golf_count}i,` +
           `reject_count=${p.reject_count}i,${colorFields},message=${str(p.message || '')},` +
           `image=${str(p.image || '')} ${p.ts}`;
}

const base = env.get('INFLUX_URL') || 'http://influxdb:8086';
msg.method = 'POST';
msg.url = `${base}/api/v2/write?org=${encodeURIComponent(env.get('INFLUX_ORG'))}` +
          `&bucket=${encodeURIComponent(env.get('INFLUX_BUCKET'))}&precision=ms`;
msg.headers = {
    'Authorization': 'Token ' + env.get('INFLUX_TOKEN'),
    'Content-Type': 'text/plain; charset=utf-8'
};
msg.payload = line;
msg.target = 'InfluxDB';
return msg;

// 4c. แจ้งเตือน Telegram เมื่อเจอ "สิ่งที่ไม่ใช่ลูกกอล์ฟ"
// กันสแปม: เรื่องเดิม (สาเหตุชุดเดิม) แจ้งซ้ำได้ไม่ถี่กว่า ALERT_COOLDOWN_SEC วินาที
const p = msg.payload;
if (!p.reject_count) return null;

const token = env.get('TELEGRAM_TOKEN');
const chatId = env.get('TELEGRAM_CHAT_ID');
if (!token || !chatId) {
    node.status({fill: 'yellow', shape: 'ring', text: 'ยังไม่ได้ตั้ง TELEGRAM_TOKEN/CHAT_ID ใน .env'});
    return null;
}

const cooldown = Number(env.get('ALERT_COOLDOWN_SEC') || 30) * 1000;
const reasons = (p.rejects || []).map(r => r.reason).sort().join(', ');
const last = context.get('last') || {};
if (last.reasons === reasons && Date.now() - last.at < cooldown) {
    node.status({fill: 'grey', shape: 'ring', text: 'ข้าม (cooldown): ' + reasons});
    return null;
}
context.set('last', {reasons: reasons, at: Date.now()});

const golfLine = p.golf_count
    ? `ลูกกอล์ฟปกติ ${p.golf_count} ลูก (ขาว ${p.colors.White} / นีออน ${p.colors.Neon} / ชมพู ${p.colors.Pink})`
    : 'ไม่มีลูกกอล์ฟในภาพ';
const text = `⚠️ พบวัตถุแปลกปลอม ${p.reject_count} ชิ้น\n` +
             `สาเหตุ: ${reasons}\n${golfLine}\n` +
             `กล้อง: ${p.device}  เวลา: ${p.time}\nภาพ: ${p.image || '-'}`;

msg.method = 'POST';
msg.url = `https://api.telegram.org/bot${token}/sendMessage`;
msg.headers = {'Content-Type': 'application/json'};
msg.payload = {chat_id: chatId, text: text};
msg.target = 'Telegram';
node.status({fill: 'red', shape: 'dot', text: 'แจ้งเตือน: ' + reasons});
return msg;

// 4b. รวบรวมเหตุการณ์ไว้ในบัฟเฟอร์ แล้วส่งไป Google Sheets ทีละชุด (Batch)
// ส่งเมื่อ: inject จับเวลาครบรอบ (topic = flush) หรือบัฟเฟอร์เต็ม 50 แถว
const MAX_ROWS = 50;
let buffer = flow.get('gsheetBuffer') || [];

if (msg.topic !== 'flush') {
    const p = msg.payload;
    buffer.push([
        p.time, p.device, p.kind, p.golf_count, p.reject_count,
        p.colors.White, p.colors.Neon, p.colors.Pink,
        (p.rejects || []).map(r => r.reason).join(', '),
        p.message, p.image || ''
    ]);
    flow.set('gsheetBuffer', buffer);
    node.status({fill: 'blue', shape: 'ring', text: `รอส่ง ${buffer.length} แถว`});
    if (buffer.length < MAX_ROWS) return null;
}

if (buffer.length === 0) return null;

const url = env.get('GSHEET_URL');
if (!url) {
    node.status({fill: 'yellow', shape: 'ring', text: `ยังไม่ได้ตั้ง GSHEET_URL (ค้าง ${buffer.length} แถว)`});
    if (buffer.length > 1000) flow.set('gsheetBuffer', buffer.slice(-1000));
    return null;
}

flow.set('gsheetBuffer', []);
node.status({fill: 'green', shape: 'dot', text: `ส่ง ${buffer.length} แถว`});
msg.method = 'POST';
msg.url = url;
msg.headers = {'Content-Type': 'application/json'};
msg.payload = {sheet: 'detections', rows: buffer};
// Apps Script บันทึกข้อมูลตอนรับ POST แล้วตอบกลับด้วย 302 ไปอีกโดเมน
// ถ้าให้ตาม redirect ไป บางครั้งได้ 405 กลับมา ทั้งที่ข้อมูลเข้า Sheet แล้ว - ไม่ต้องตาม
msg.followRedirects = false;
msg.target = 'Google Sheets';
return msg;

// ตรวจผลตอบกลับของ HTTP ทุกปลายทาง แสดงสถานะบนโหนด และเตือนเมื่อพัง
const ok = msg.statusCode >= 200 && msg.statusCode < 400;
const stats = context.get('stats') || {};
const s = stats[msg.target] || {ok: 0, fail: 0};
ok ? s.ok++ : s.fail++;
stats[msg.target] = s;
context.set('stats', stats);

node.status({
    fill: ok ? 'green' : 'red', shape: 'dot',
    text: Object.entries(stats).map(([k, v]) => `${k} ✓${v.ok} ✗${v.fail}`).join('  ')
});
if (!ok) {
    node.warn(`${msg.target} ตอบกลับ ${msg.statusCode}: ` +
              (typeof msg.payload === 'string' ? msg.payload : JSON.stringify(msg.payload)).slice(0, 300));
    return msg;
}
return null;
